import numpy as np, sys
sys.path.insert(0,'.')
from gen4_tests import padua, cheb_basis
# Christoffel-number test for Padua as a near-minimal rule of degree 2n-1 for the product Chebyshev measure:
# are the Padua weights w_B = 1/K_{n}(B,B) with K the *reproducing kernel of the discrete-orthogonal basis*? i.e. w_B = 1/K_n^{disc}(B,B) (true for any interpolatory rule: w_B = <l_B,1>; Christoffel property w_B = 1/sum phi_j(B)^2 holds for orthonormal phi w.r.t. the rule itself trivially). Nontrivial version: w_B = 1/K_{n-1}^{cont}(B,B) + correction? measured earlier: w_B = 1/(K_n^{cont}(B,B) - T_n(x_B)^2) exactly.
for n in (4,8,16):
    P,w=padua(n); V,idx=cheb_basis(P[:,0],P[:,1],n); K=np.sum(V**2,axis=1)
    Vm,_=cheb_basis(P[:,0],P[:,1],n-1); Km=np.sum(Vm**2,axis=1)
    Tnx=np.cos(n*np.arccos(np.clip(P[:,0],-1,1))); Tny=np.cos(n*np.arccos(np.clip(P[:,1],-1,1)))
    # degree-n block contributions: sum over i+j=n of (sqrt2 Ti sqrt2 Tj)^2 ; Padua nodes: T_n(x)^2 term with weight... check w_B vs 1/(K_{n-1} + s) for s = block sum minus Tn(x)^2
    blk=K-Km
    print('n',n,'max|w*(K_n - Tn(x)^2) - 1| %.1e'%np.max(np.abs(w*(K-Tnx**2)-1)),'| max|w*K_{n-1}-1| %.3f'%np.max(np.abs(w*Km-1)),'| mean block/K %.3f'%np.mean(blk/K), '| Tn(x_B)^2 values',np.unique(np.round(Tnx**2,6)), ' Tn(y_B)^2', np.unique(np.round(Tny**2,6))[:4])
# Gauss-type characterisation: Padua nodes are common zeros of which degree-n and degree-(n+1) polynomials? (Known: ideal generated by T_{n+1}(x)-T_{n-1}(x) and the mixed generator). Count: dim of degree-(n+1) polys vanishing on Pad_n.
for n in (4,6,8):
    P,w=padua(n); V,idx=cheb_basis(P[:,0],P[:,1],n+1)
    s=np.linalg.svd(V,compute_uv=False); null=np.sum(s<1e-10*s[0]); 
    Vn,idxn=cheb_basis(P[:,0],P[:,1],n); sn=np.linalg.svd(Vn,compute_uv=False)
    print('n',n,'dim Pi_{n+1}',len(idx),'N',len(P),'nullity of V_{n+1} on Pad_n',null,'= n+2?',null==n+2,'| V_n nullity',np.sum(sn<1e-10*sn[0]))
